cd /workspace/nox/web/site; [ -f studio.html.bak_w3_1 ] || cp studio.html studio.html.bak_w3_1
echo '' | base64 -d | gunzip > nox-studio-x.js
echo '' | base64 -d | gunzip > nox-studio-x.css
python3 - <<'P'
p='/workspace/nox/web/site/studio.html'; s=open(p,encoding='utf-8').read()
if 'nox-studio-x' not in s:
    s=s.replace('</head>','<link rel="stylesheet" href="./nox-studio-x.css?v=1">\n</head>',1).replace('</body>','<script type="module" src="./nox-studio-x.js?v=1"></script>\n</body>',1)
    open(p,'w',encoding='utf-8').write(s); print('patched')
P
echo '' | base64 -d | gunzip > /tmp/w3s.py
/workspace/nox/venv/bin/python /tmp/w3s.py studioA http://127.0.0.1:8091/web/studio.html 2>&1
